class Leads(Product):
    """Lapisite Leads: the catalogue of prospects and their leases (``client.leads``)."""

    def list_leads_catalogue(
        self,
        *,
        sector: Optional[str] = None,
        category: Optional[str] = None,
        city: Optional[str] = None,
        ad_source: Optional[str] = None,
        updated_since: Optional[str] = None,
        cursor: Optional[str] = None,
        limit: Optional[int] = None,
        accept_language: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> types.LeadsCataloguePage:
        """Browse the catalogue

        ``GET /v1/leads/catalogue/`` · scopes: leads:read.
        Lists every lead of the catalogue, filtered by sector, trade, city, ad source and last update, one page at a time (`limit`, `cursor`).
        """
        return self._client.call(  # type: ignore[no-any-return]
            _OPS["listLeadsCatalogue"],
            query={"sector": sector, "category": category, "city": city, "ad_source": ad_source, "updated_since": updated_since, "cursor": cursor, "limit": limit},
            accept_language=accept_language,
            options=options,
        )

    def iter_list_leads_catalogue(
        self,
        *,
        sector: Optional[str] = None,
        category: Optional[str] = None,
        city: Optional[str] = None,
        ad_source: Optional[str] = None,
        updated_since: Optional[str] = None,
        limit: Optional[int] = None,
        accept_language: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> Iterator[types.LeadsCatalogueItem]:
        """Every item of ``list_leads_catalogue``, page after page (``next_cursor`` → ``?cursor=``)."""
        return self._client.paginate(
            _OPS["listLeadsCatalogue"],
            query={"sector": sector, "category": category, "city": city, "ad_source": ad_source, "updated_since": updated_since, "limit": limit},
            accept_language=accept_language,
            options=options,
        )

